import json
from datetime import datetime

def update_memories(facts, memories, policies, updates):
    # Parse JSON data
    facts = json.loads(facts)
    memories = json.loads(memories)
    policies = json.loads(policies)
    updates = json.loads(updates)

    # Create dictionaries for easy lookup
    fact_dict = {f['id']: f for f in facts}
    memory_dict = {m['id']: m for m in memories}
    policy_dict = {p['id']: p for p in policies}
    update_dict = {u['id']: u for u in updates}

    # Process updates
    for update in updates:
        update_id = update['id']
        update_date = datetime.strptime(update['observed'], '%Y-%m-%d')
        update_text = update['text']

        for memory_id in memory_dict:
            memory = memory_dict[memory_id]
            if memory['id'] in update_text:
                # Check if update is credible
                if update_date > datetime.strptime(fact_dict[memory_id]['observed'], '%Y-%m-%d'):
                    # Check if update is relevant
                    if 'retract' in update_text or 'false' in update_text:
                        # Withdraw memory if update is credible and relevant
                        memories[update_id] = 'withdraw'
                    elif 'replace' in update_text or 'new' in update_text:
                        # Recompute memory if update is credible and relevant
                        memories[update_id] = 'recompute'
                    elif 'doubt' in update_text or 'uncertain' in update_text:
                        # Uncertain memory if update is credible and relevant
                        memories[update_id] = 'uncertain'

    # Process policies
    for policy in policies:
        policy_id = policy['id']
        policy_text = policy['text']

        for memory_id in memory_dict:
            memory = memory_dict[memory_id]
            if policy_id in policy_text:
                # Check if memory still follows from credible facts under the policy
                if any(fact_id in update_text for fact_id in memory['supports']):
                    # Keep memory if it still follows from credible facts under the policy
                    memories[memory_id] = 'keep'

    # Filter out memories that are not 'withdraw', 'recompute', or 'uncertain'
    changes = {memory_id: memory for memory_id, memory in memories.items() if memory != 'keep'}

    return json.dumps({'changes': changes})

